    static RestPostmanEndpointBuilder endpointBuilder(String componentName, String path) {
        class RestPostmanEndpointBuilderImpl extends AbstractEndpointBuilder implements RestPostmanEndpointBuilder, AdvancedRestPostmanEndpointBuilder {
            public RestPostmanEndpointBuilderImpl(String path) {
                super(componentName, path);
            }
        }
        return new RestPostmanEndpointBuilderImpl(path);
    }
